+
+		if (count($MyRow) == 1 and trim($MyRow[0]) == '') { // blank line
+			continue;
+		}
+
+		if (count($MyRow) != $FieldTarget) {
+			prnMsg($FieldTarget . ' ' . __('fields required') . ', ' . count($MyRow) . ' ' . __('fields received') . ' (' . __('row') . ' ' . $Row . ')', 'error');
