+		} elseif (!Is_Date($MyRow[2])) {
+			$InputError = 1;
+			prnMsg(__('The date of the note must be a valid date') . ' (' . __('row') . ' ' . $Row . ')', 'error');
+		} else {
+			$NoteDate = FormatDateForSQL($MyRow[2]);
+		}
+
+		if ($InputError != 1) {
+			$SQL = "INSERT INTO stocknotes (stockid,
